function posFor(w, h, pad, where){ var x, y; switch(where){ case 'center': x=w/2; y=h/2; break; case 'top-left': x=pad; y=pad; break; case 'top-right': x=w-pad; y=pad; break; case 'bottom-left': x=pad; y=h-pad; break; default: x=w-pad; y=h-pad; } return {x:x, y:y}; }
function tileCount(w, h, tile, minGap){ tile=(tile==null)?120:tile; minGap=(minGap==null)?20:minGap; var nx=Math.max(1, Math.floor((w - minGap)/(tile+minGap))); var ny=Math.max(1, Math.floor((h - minGap)/(tile+minGap))); return {nx:nx, ny:ny, total:nx*ny}; }
var EXPORTS={ posFor:posFor, tileCount:tileCount };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WatermarkForgePure = EXPORTS; }
